def counted(fn):
    """Wrap fn so wrapper.calls counts how many times it was called."""
    def wrapper(*args, **kwargs):
        # bump wrapper.calls, then call fn and return its result
        pass
    wrapper.calls = 0
    return wrapper

@counted
def greet():
    return "hi"

greet(); greet(); greet()
print(greet.calls)

