import functools

def logged(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        result = fn(*args, **kwargs)
        wrapper.log.append(f"{fn.__name__}{args} -> {result}")
        return result
    wrapper.log = []
    return wrapper

@logged
def area(w, h):
    return w * h

@logged
def greet(name):
    return "hi " + name

area(3, 4)
area(2, 5)
greet("Kavi")
print(area.__name__, area.log)
print(greet.log)

